div.script:
    (function() {
        var pageId  = 'h1f17xvq280n2mbh';
        var pageUrl = '/sports/wbkb/2025-26/boxscores/20260226_svaw.xml';

        function buildAriaLabel(label, relatedEvt) {
            if (!relatedEvt) return label;
            var a = relatedEvt.sport + ' event: ' + relatedEvt.date + ' ';
            if (relatedEvt.team1) {
                a += relatedEvt.team1;
                if (relatedEvt.team2) { a += ' ' + relatedEvt.ariaVsOrAt + ' ' + relatedEvt.team2; }
                a += ':';
            }
            if (relatedEvt.neutralSite) { a += ' @ ' + relatedEvt.neutralSite + ':'; }
            a += ' ' + label;
            return a;
        }

        let url = '/action/content/scheduleRelatedLinks.json?pageId=' + encodeURIComponent(pageId) + '&pageUrl=' + encodeURIComponent(pageUrl);
        fetch(url).then(res => res.json()).then(relatedEvts => {
            var relatedEvt;
            var relatedEvtLinks;
            if (relatedEvts && relatedEvts.length > 0) {
                relatedEvt = relatedEvts[0];
                if (relatedEvt.links && relatedEvt.links.length > 0) {
                    relatedEvtLinks = relatedEvt.links;
                }
                relatedEvt.ariaVsOrAt = (relatedEvt.neutralSite && relatedEvt.neutralSite.length > 0) || relatedEvt.home ? 'vs.' : 'at';
            }

            url = '/action/content/relatedLinks.json?pageId=' + encodeURIComponent(pageId);
            fetch(url).then(res => res.json()).then(links => {
                if (!links) { links = []; }

                var eventLinks = relatedEvtLinks || [];
                // add StatView link from schedule event if present
                for (var k = 0; k < eventLinks.length; k++) {
                    if (eventLinks[k].mapType === 'SV') {
                        links.push({ id: null, text: eventLinks[k].text, mapType: 'SV', url: eventLinks[k].url });
                        break;
                    }
                }
                if (links.length === 0) { return; }
                var printed = {};
                var parts   = [];
                for (var i = 0; i < links.length; i++) {
                    var id      = links[i].id;
                    var text    = links[i].text;
                    var url     = links[i].url;
                    var mapType = links[i].mapType;

                    // Apply event-link override
                    for (var j = 0; j < eventLinks.length; j++) {
                        if (eventLinks[j].url === url) {
                            text    = eventLinks[j].text;
                            url     = eventLinks[j].url;
                            mapType = eventLinks[j].mapType;
                            break;
                        }
                    }

                    var counter = printed.hasOwnProperty(text) ? printed[text] + 1 : 1;
                    var label   = counter > 1 ? text + ' ' + counter : text;
                    printed[text] = counter;

                    var item;
                    var ariaLabel  = buildAriaLabel(label, relatedEvt);
                    var isExternal = (url.indexOf('http') === 0 || url.indexOf('/links') === 0) &&
                            url.indexOf(window.location.host) === -1;
                    var cssClass = "list-group-item bg-primary text-white d-inline-block" + (pageId === id ? " font-weight-bold" : "");
                    var icon = '';
                    switch(mapType) {
                        case "GA":                             icon = '';
                            break;
                        case "TI":                             icon = '';
                            break;
                        case "RC":                             icon = '';
                            break;
                        case "PR":                             icon = '';
                            break;
                        case "LS":                             icon = '';
                            break;
                        case "VI":                             icon = '';
                            break;
                        case "AU":                             icon = '';
                            break;
                        case "DI":                             icon = '';
                            break;
                        case "BS":                             icon = '';
                            break;
                        case "RE":                             icon = '';
                            break;
                        case "LI":                             icon = '';
                            break;
                    }
                    item = ''
                            + icon
                            + ' ' + text + ''
                            + '';
                    parts.push(item);
                }

                var container = document.getElementById('related-links-' + pageId);
                if (container && parts.length > 0) {
                    container.innerHTML = parts.join('');
                    container.style.display = '';
                }
            });
        });
    })();

body.script:
$(function() {
	if (readCookie('adminuser')) {
		$('body').append('Edit Page');
		$('#edit-page-btn').click(function() {
			url = document.location.protocol + '//' + document.location.hostname
			if (document.location.port) url += ':' + document.location.port;
			url += '/admin/content/wiki/g2g';
			url += document.location.pathname;
			window.location = url;
		});
	}
});

$(function() {
  if (window.self == window.top) {
    return;
  }
  var heroic = document.referrer.indexOf("herosports.com/");
  if (heroic > -1) {
    alert("We do not allow HERO Sports to frame our site.");
    window.top.location = window.location;
  }
});

    $(document).ready(function() {
        var el = $('#gdpr-compliance');
        var page = window.location.pathname; // Fetch the current request URI
        var id = el.data("id") || el.attr('id');
        var gdprType = "compliance";

        var dateAux = new Date();
        var dateAuxString = dateAux.toISOString().replace('T', ' ').replace('Z', '').split('.')[0] + '.' + dateAux.getMilliseconds();

        var gdpr = $('#' + id);
        var cookieHandler = new $.PRESTO.CookieHandler();
        var cookieName = "gdpr_" + gdprType;

        // Check if the page contains "sidekick-index" and set the cookie
        if (page.includes("sidekick-index")) {
            cookieHandler.createCookie(cookieName, 'p', 365);
            console.log("GDPR accepted on sidekick-index, cookies set with current date and time:", dateAuxString);
        } else if (!cookieHandler.readCookie(cookieName)) {
            gdpr.addClass("show");

            gdpr.find('.gdpr-close').click(function() {
                gdpr.removeClass("show");
                return false;
            });

            gdpr.find('.gdpr-accept').click(function(e) {
                e.preventDefault();
                gdpr.removeClass("show");
                cookieHandler.createCookie(cookieName, 'p', 365);
                console.log("GDPR accepted, cookies set with current date and time:", dateAuxString);
            });
        } else {
            console.log("GDPR cookie already present.");
        }
    });

var nm = document.createElement('script');
nm.defer = 'defer';
